script:
(function () {
  'use strict';
  // Common-size statements and year-over-year changes for two years.
  //   Balance sheet: every line as % of total assets. Total current assets = cash + receivables +
  //   inventory + other current; total assets = current + PP&E + other long-term; liabilities summed
  //   the same way; shareholders' equity = total assets - total liabilities.
  //   Income statement: every line as % of revenue. Gross profit = revenue - COGS; operating income =
  //   gross profit - SG&A - D&A; pre-tax income = operating income - interest + other income;
  //   net income = pre-tax income - income taxes.
  //   Change = current - prior; % change = change / |prior| ("n/a" when prior is 0).
  // Verified in Node (scratchpad tests/b2biz), hand-checked with the default figures: total assets
  //   $550,000 -> $600,000 (+9.1%), equity $280,000 -> $300,000 (+7.1%), cash 7.3% -> 8.3% of assets;
  //   revenue $900,000 -> $1,000,000 (+11.1%), gross margin 38.9% -> 40.0%, net income $67,000 ->
  //   $105,000 (+56.7%), net margin 7.4% -> 10.5%. A prior-year net loss of -$10,000 rising to
  //   +$5,000 shows +150.0%; zero totals show n/a, never NaN/Infinity.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var one = new Intl.NumberFormat('en-US', { minimumFractionDigits: 1, maximumFractionDigits: 1 });

  // Statement layout. type 'in' = entered line, 'sum' = calculated subtotal; sign for income lines.
  var BALANCE = [
    { label: 'Assets', head: true },
    { key: 'Cash', label: 'Cash and equivalents' },
    { key: 'Rec', label: 'Accounts receivable' },
    { key: 'Inv', label: 'Inventory' },
    { key: 'Oca', label: 'Other current assets' },
    { key: 'TCA', label: 'Total current assets', sum: true },
    { key: 'Ppe', label: 'Property, plant and equipment (net)' },
    { key: 'Olta', label: 'Other long-term assets' },
    { key: 'TA', label: 'Total assets', sum: true },
    { label: 'Liabilities and equity', head: true },
    { key: 'Pay', label: 'Accounts payable' },
    { key: 'Std', label: 'Short-term debt' },
    { key: 'Ocl', label: 'Other current liabilities' },
    { key: 'TCL', label: 'Total current liabilities', sum: true },
    { key: 'Ltd', label: 'Long-term debt' },
    { key: 'Oltl', label: 'Other long-term liabilities' },
    { key: 'TL', label: 'Total liabilities', sum: true },
    { key: 'EQ', label: 'Shareholders\' equity', sum: true },
    { key: 'TLE', label: 'Total liabilities and equity', sum: true }
  ];
  var INCOME = [
    { key: 'Rev', label: 'Revenue' },
    { key: 'Cogs', label: 'Cost of goods sold' },
    { key: 'GP', label: 'Gross profit', sum: true },
    { key: 'Sga', label: 'Selling, general and administrative' },
    { key: 'Da', label: 'Depreciation and amortization' },
    { key: 'OI', label: 'Operating income', sum: true },
    { key: 'Int', label: 'Interest expense' },
    { key: 'Oth', label: 'Other income (expense)' },
    { key: 'PTI', label: 'Pre-tax income', sum: true },
    { key: 'Tax', label: 'Income taxes' },
    { key: 'NI', label: 'Net income', sum: true }
  ];
  var INPUTS = ['Cash', 'Rec', 'Inv', 'Oca', 'Ppe', 'Olta', 'Pay', 'Std', 'Ocl', 'Ltd', 'Oltl',
                'Rev', 'Cogs', 'Sga', 'Da', 'Int', 'Oth', 'Tax'];
  var MAY_BE_NEGATIVE = { Oth: true, Tax: true };

  // --- calc ---
  function totals(v) {
    var t = {};
    Object.keys(v).forEach(function (k) { t[k] = v[k]; });
    t.TCA = v.Cash + v.Rec + v.Inv + v.Oca;
    t.TA = t.TCA + v.Ppe + v.Olta;
    t.TCL = v.Pay + v.Std + v.Ocl;
    t.TL = t.TCL + v.Ltd + v.Oltl;
    t.EQ = t.TA - t.TL;
    t.TLE = t.TL + t.EQ;
    t.GP = v.Rev - v.Cogs;
    t.OI = t.GP - v.Sga - v.Da;
    t.PTI = t.OI - v.Int + v.Oth;
    t.NI = t.PTI - v.Tax;
    return t;
  }

  function share(x, base) { return base > 0 ? x / base : null; }
  function change(prior, current) { return prior !== 0 ? (current - prior) / Math.abs(prior) : null; }
  // --- end calc ---

  function el(id) { return document.getElementById(id); }
  function setText(id, text) { el(id).textContent = text; }

  function read(id) {
    var raw = String(el(id).value).trim();
    if (raw === '') return 0;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function pct(x) { return x === null ? 'n/a' : one.format(x * 100) + '%'; }
  function signedPct(x) { return x === null ? 'n/a' : (x > 0 ? '+' : '') + one.format(x * 100) + '%'; }
  function signedMoney(x) { return (x > 0 ? '+' : x < 0 ? '−' : '') + money.format(Math.abs(x)); }

  function cell(tag, text, strong) {
    var c = document.createElement(tag);
    if (tag === 'th') c.scope = 'row';
    if (strong) {
      var s = document.createElement('strong');
      s.textContent = text;
      c.appendChild(s);
    } else c.textContent = text;
    return c;
  }

  function fill(bodyId, layout, p, c, baseKey) {
    var body = el(bodyId);
    body.textContent = '';
    layout.forEach(function (line) {
      var tr = document.createElement('tr');
      if (line.head) {
        var th = document.createElement('th');
        th.scope = 'rowgroup';
        th.colSpan = 7;
        th.textContent = line.label;
        tr.appendChild(th);
      } else {
        var a = p[line.key], b = c[line.key];
        var bold = !!line.sum;
        tr.appendChild(cell('th', line.label, bold));
        [money.format(a), pct(share(a, p[baseKey])), money.format(b), pct(share(b, c[baseKey])),
         signedMoney(b - a), signedPct(change(a, b))].forEach(function (text) { tr.appendChild(cell('td', text, bold)); });
      }
      body.appendChild(tr);
    });
  }

  function update() {
    var p = {}, c = {}, bad = false;
    INPUTS.forEach(function (k) {
      p[k] = read('bs' + k + 'P');
      c[k] = read('bs' + k + 'C');
      [p[k], c[k]].forEach(function (v) { if (isNaN(v) || (v < 0 && !MAY_BE_NEGATIVE[k])) bad = true; });
    });
    var error = el('bsError');
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter numbers only. Every line except other income and income taxes must be 0 or more (blank counts as 0).';
      ['bsRevChange', 'bsNiChange', 'bsTaChange', 'bsEqChange', 'bsGmP', 'bsGmC', 'bsOmP', 'bsOmC', 'bsNmP', 'bsNmC', 'bsDebtP', 'bsDebtC']
        .forEach(function (id) { setText(id, '–'); });
      el('bsBalanceBody').textContent = '';
      el('bsIncomeBody').textContent = '';
      el('bsWarning').hidden = true;
      return;
    }
    var tp = totals(p), tc = totals(c);
    setText('bsRevChange', signedPct(change(tp.Rev, tc.Rev)));
    setText('bsNiChange', signedPct(change(tp.NI, tc.NI)));
    setText('bsTaChange', signedPct(change(tp.TA, tc.TA)));
    setText('bsEqChange', signedPct(change(tp.EQ, tc.EQ)));
    setText('bsGmP', pct(share(tp.GP, tp.Rev))); setText('bsGmC', pct(share(tc.GP, tc.Rev)));
    setText('bsOmP', pct(share(tp.OI, tp.Rev))); setText('bsOmC', pct(share(tc.OI, tc.Rev)));
    setText('bsNmP', pct(share(tp.NI, tp.Rev))); setText('bsNmC', pct(share(tc.NI, tc.Rev)));
    setText('bsDebtP', pct(share(tp.TL, tp.TA))); setText('bsDebtC', pct(share(tc.TL, tc.TA)));
    ['P', 'C'].forEach(function (s) {
      var t = s === 'P' ? tp : tc;
      setText('bsTCA' + s, money.format(t.TCA)); setText('bsTA' + s, money.format(t.TA));
      setText('bsTL' + s, money.format(t.TL)); setText('bsEQ' + s, money.format(t.EQ));
      setText('bsNI' + s, money.format(t.NI));
    });
    fill('bsBalanceBody', BALANCE, tp, tc, 'TA');
    fill('bsIncomeBody', INCOME, tp, tc, 'Rev');

    var warn = [];
    if (tp.EQ < 0 || tc.EQ < 0) warn.push('Liabilities are larger than assets in at least one year, so shareholders\' equity is negative.');
    if (tp.TA <= 0 || tc.TA <= 0) warn.push('Total assets are zero in at least one year, so the balance sheet percentages show n/a.');
    if (tp.Rev <= 0 || tc.Rev <= 0) warn.push('Revenue is zero in at least one year, so the income statement percentages show n/a.');
    el('bsWarning').hidden = warn.length === 0;
    setText('bsWarningText', warn.join(' '));
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('bsForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
